// ****** // https://twitter.com/SamuelAnn0924
// ****** // https://www.instagram.com/samuel_yan_1990/

var mySize, angle;
var seed = Math.random() * 2965;
var color1;
let colors1 = "ba87ff-f5989d-e3d7a3".split("-").map((a) => "#" + a );
let colors2 = "6cbbd4-5863b1-c1f29b".split("-").map((a) => "#" + a );
let colors3 = "1b1b1b-f3f3f3-ff0000".split("-").map((a) => "#" + a );
let colors4 = "aaf0d3-50514f-ffe066".split("-").map((a) => "#" + a );
let colors5 = "5883fa-e36c2d-c511e4".split("-").map((a) => "#" + a );
let colorbg = "ffffff".split("-").map((a) => "#" + a);
let colorbg2 = "ffffff01".split("-").map((a) => "#" + a);
var t, timer;

function setup() {
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	background(255);
	t = timer = 0;
	rez = c = n = 0.01;
	color1 = random([colors1, colors2, colors3, colors4, colors5]);
	// pixelDensity(5);
	xOff = 0;
	yOff = 0;
	angle = 0;
}

function draw() {
	randomSeed(seed);
	// background(colorbg2);
	noFill();
	let plus = random(20, 200);
	for (let i = xOff; i < width - xOff; i += plus) {
		for (let j = yOff; j < height - yOff; j += plus) {
			for (let k = 0; k < 4; k++) {
				strokeWeight(random(0.1,0.25*k));
				strokeCap(SQUARE);
				var n = noise(i * rez + t, j * rez + t);
				stroke(random(color1));

				if (n > 0.5) {
					push();
					translate(i, j);
					rotate(random([PI / 2, PI, -PI / 2, -PI]) + angle);
					line(0, 0, -plus, plus);
					line(-plus, -plus, 0, 0);
					pop();
				} else {
					push();
					translate(i, j);
					rotate(random([PI / 2, PI, -PI / 2, -PI]) + angle);
					line(0, 0, plus, plus);
					line(plus, -plus, 0, 0);
					pop();
				}
			}
		}
	}
	if (angle < PI) angle += TAU / 360 * random(0.1, 0.8);
	else noLoop();
}

function keyPressed() {
	//noLoop();
	saveCanvas("GENUARY 2022_0117_3 colors Surface", "jpg");
}

